def is_2_5_smooth(k):
    if k == 1:
        return True
    if k < 1:
        return False
    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5
    return k == 1

# We test n = 0, 1, 2, ..., 50
results = []
