def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_condition(n):
    if n < 0:
        return False
    divisor = D(n)
    if divisor == 0: # Should not happen for n >= 0
        return False

    # Check if 20**(n+1) is divisible by divisor
    # Use modular arithmetic, although since we are checking for divisibility, 
    # we can use standard integer division.
    try:
        power_of_20 = 20**(n + 1)
        return power_of_20 % divisor == 0
    except OverflowError:
        # For extremely large n, this could be an issue, but for small n it's fine.
        return False

solutions = []
for n in range(11):
    if check_condition(n):
        solutions.append(n)

print(f"Solutions found for n in [0, 10]: {solutions}")

